import sys
from collections import Counter, OrderedDict

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    elements = list(map(int, data[1:1+n]))

    # Handle edge cases
    if n == 0 or not elements:
        return

    # Count frequencies
    freq = Counter(elements)

    # Track first appearance
    first_appearance = {}
    for idx, val in enumerate(elements):
        if val not in first_appearance:
            first_appearance[val] = idx

    # Sort by frequency (descending), then by first appearance (ascending)
    sorted_elements = sorted(freq.keys(), key=lambda x: (-freq[x], first_appearance[x]))

    # Output results
    for elem in sorted_elements:
        print(f"{elem}:{freq[elem]}")

if __name__ == "__main__":
    main()
